syntax:
class AbstractClass {
    virtual void pureVirtualFunction() = 0; // pure virtual function
};

// Usage restrictions:
// - Cannot instantiate objects of AbstractClass
// - Cannot use AbstractClass as a parameter or return type by value
// - Can declare pointers or references to AbstractClass

// Examples:
// AbstractClass obj; // Error: cannot instantiate
// AbstractClass f(); // Error: cannot return by value
// void g(AbstractClass); // Error: parameter by value
// AbstractClass& h(AbstractClass&); // OK: reference parameter

code_example:
#include <iostream>

class Shape {
public:
    virtual void draw() const = 0; // pure virtual function making Shape an abstract class
    virtual ~Shape() = default; // virtual destructor
};

class Circle : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing Circle" << std::endl;
    }
};

void renderShape(const Shape& shape) {
    shape.draw();
}

int main() {
    // Shape s; // Error: cannot instantiate abstract class
    Circle c;
    renderShape(c); // OK: passing by reference to abstract class
    // Shape* p = new Shape(); // Error: cannot instantiate abstract class
    Shape* p = new Circle(); // OK: pointer to abstract class pointing to derived object
    p->draw();
    delete p;
    return 0;
}
